const keywords = [
  "properti",
  "property",
  "real estate",
  "perumahan",
  "rumah",
  "apartemen",
  "kpr",
  "developer",
  "residensial",
  "hunian"
];

return $input.all().filter(item => {
  const text = (item.json.title || "").toLowerCase();
  return keywords.some(k => text.includes(k));
});

const items = $input.all().filter(i => i.json.title && i.json.link);
if (!items.length) { return []; }

items.sort((a, b) => {
  const da = new Date(a.json.isoDate || a.json.pubDate || 0).getTime();
  const db = new Date(b.json.isoDate || b.json.pubDate || 0).getTime();
  return db - da;
});

const top = items[0].json;

let source = top.creator || top.author || '';
const dashSplit = String(top.title).split(' - ');
if (!source && dashSplit.length > 1) { source = dashSplit[dashSplit.length - 1].trim(); }

return [{
  json: {
    title: top.title,
    link: top.link,
    contentSnippet: top.contentSnippet || top.content || '',
    pubDate: top.isoDate || top.pubDate || '',
    source: source || 'News source',
  },
}];

const link = String($json.link || '');
let base64 = '';
try {
  const u = new URL(link);
  const parts = u.pathname.split('/').filter(Boolean);
  const idx = parts.findIndex(p => p === 'articles' || p === 'read');
  if (idx !== -1 && parts[idx + 1]) { base64 = parts[idx + 1]; }
} catch (e) { base64 = ''; }
// Fallback: plain string parse
if (!base64) {
  const marker = '/articles/';
  const mIdx = link.indexOf(marker);
  if (mIdx !== -1) {
    let rest = link.slice(mIdx + marker.length);
    const q = rest.indexOf('?');
    if (q !== -1) { rest = rest.slice(0, q); }
    base64 = rest;
  }
}
return { json: { ...$json, base64Str: base64 } };

const html = String($json.data || $json.body || '');
function attr(name) {
  const idx = html.indexOf(name + '="');
  if (idx === -1) { return ''; }
  const start = idx + name.length + 2;
  const end = html.indexOf('"', start);
  return end === -1 ? '' : html.slice(start, end);
}
const signature = attr('data-n-a-sg');
const timestamp = attr('data-n-a-ts');
const base64 = $('Extract Article ID').item.json.base64Str;

const inner = '["garturlreq",[["X","X",["X","X"],null,null,1,1,"US:en",null,1,null,null,null,null,null,0,1],"X","X",1,[1,1,1],1,1,null,0,0,null,0],"' + base64 + '",' + timestamp + ',"' + signature + '"]';
const freq = JSON.stringify([[["Fbv4je", inner]]]);

return { json: { base64Str: base64, signature: signature, timestamp: timestamp, freq: freq } };

const text = String($json.data || $json.body || '');
let decoded = '';
try {
  const parts = text.split('\n\n');
  const part = parts.length > 1 ? parts[1] : text;
  const arr = JSON.parse(part);
  for (const row of arr) {
    if (Array.isArray(row) && row[0] === 'wrb.fr' && row[2]) {
      decoded = JSON.parse(row[2])[1];
      break;
    }
  }
} catch (e) { decoded = ''; }

const a = $('Pick Latest Article').item.json;
return { json: { ...a, realUrl: decoded || a.link } };

const html = String($json.data || $json.body || '');

// Plain-string meta tag reader (no regex): find the <meta> tag that mentions
// the property, then read its content="" / content='' value.
function meta(prop) {
  const lower = html.toLowerCase();
  let searchFrom = 0;
  while (true) {
    const propIdx = lower.indexOf(prop.toLowerCase(), searchFrom);
    if (propIdx === -1) { return ''; }
    const tagStart = lower.lastIndexOf('<meta', propIdx);
    const tagEnd = html.indexOf('>', propIdx);
    searchFrom = propIdx + prop.length;
    if (tagStart === -1 || tagEnd === -1) { continue; }
    const tag = html.slice(tagStart, tagEnd);
    const key = 'content=';
    const cIdx = tag.toLowerCase().indexOf(key);
    if (cIdx === -1) { continue; }
    const quote = tag.charAt(cIdx + key.length);
    const valStart = cIdx + key.length + 1;
    const valEnd = tag.indexOf(quote, valStart);
    if (valEnd === -1) { continue; }
    return tag.slice(valStart, valEnd).trim();
  }
}

const a = $('Parse Real URL').item.json;
const imageUrl = meta('og:image') || meta('twitter:image') || '';
const source = meta('og:site_name') || a.source;
const description = meta('og:description') || a.contentSnippet;

const cleanTitle = a.title
  .replace(/\s*\|\s*[^|]+$/, '')
  .replace(/\s*-\s*[^-]+$/, '')
  .trim();

return [{
  json: {
    title: cleanTitle,
    url: a.realUrl,
    source: source,
    pubDate: a.pubDate,
    contentSnippet: description,
    imageUrl: imageUrl,
  },
}];

const raw = String($json.text || $json.response || $json.output || '').trim();

let clean = raw;
if (clean.slice(0, 3) === '\u0060\u0060\u0060') {
  clean = clean.replace(/^\u0060\u0060\u0060(json)?/i, '');
  const lastFence = clean.lastIndexOf('\u0060\u0060\u0060');
  if (lastFence !== -1) { clean = clean.slice(0, lastFence); }
  clean = clean.trim();
}

if (clean.charAt(0) !== '{') {
  const s = clean.indexOf('{');
  const e = clean.lastIndexOf('}');
  if (s !== -1 && e !== -1) { clean = clean.slice(s, e + 1); }
}

let parsed = {};
try { parsed = JSON.parse(clean); } catch (err) { parsed = {}; }

const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags.join(' ') : (parsed.hashtags || '');
const article = $('Extract News Image URL').item.json;

return [{
  json: {
    title: article.title,
    url: article.url,
    source: article.source,
    pubDate: article.pubDate,
    imageUrl: article.imageUrl,
    summary: parsed.summary || '',
    caption: parsed.caption || '',
    hashtags: hashtags,
  },
}];
